<?php $video = $video ?? []; ?>
<form class="editor-form" method="post" enctype="multipart/form-data" action="<?= !empty($video['id']) ? url('/admin/videos/'.$video['id']) : url('/admin/videos') ?>"><?= csrf_field() ?>
<?php if ($error): ?><div class="form-error full"><?= e($error) ?></div><?php endif; ?>
<section class="form-main admin-panel"><h2>Contenido del video</h2><label>Título *<input name="title" required maxlength="180" value="<?= e($video['title'] ?? '') ?>" placeholder="Título que aparecerá en VecinoSS TV"></label><label>Descripción<textarea name="description" rows="4" maxlength="350" placeholder="Breve descripción del contenido"><?= e($video['description'] ?? '') ?></textarea></label><label>URL del video *<input type="url" name="video_url" required maxlength="1000" value="<?= e($video['video_url'] ?? '') ?>" placeholder="https://youtube.com/watch?v=... o URL de otro medio"></label><span class="hint">Compatible con YouTube, Vimeo, archivos MP4/WebM y enlaces a otras plataformas.</span></section>
<aside><section class="admin-panel"><h2>Publicación</h2><label>Estado<select name="status"><option value="draft" <?= ($video['status'] ?? '') === 'draft' ? 'selected' : '' ?>>Borrador</option><option value="published" <?= ($video['status'] ?? 'published') === 'published' ? 'selected' : '' ?>>Publicado</option></select></label><label>Fecha y hora<input type="datetime-local" name="published_at" value="<?= e(isset($video['published_at']) ? date('Y-m-d\TH:i', strtotime($video['published_at'])) : date('Y-m-d\TH:i')) ?>"></label><button class="primary-button">Guardar video →</button></section><section class="admin-panel"><h2>Imagen de portada</h2><?php if (!empty($video['cover_image'])): ?><img class="video-cover-preview" src="<?= e(post_image($video['cover_image'])) ?>" alt="Portada actual"><?php endif; ?><label>Subir imagen<input type="file" name="upload" accept="image/jpeg,image/png,image/webp"></label><span class="hint">JPG, PNG o WebP. Máximo 5 MB.</span><label>o URL externa<input type="url" name="cover_image" value="<?= e($video['cover_image'] ?? '') ?>" placeholder="https://..."></label></section></aside>
</form>
